import type { ComplianceCard as Card } from '../types'

// Two separate tracks: compliance and supply risk. Never mix them.
export function ComplianceCard({ card }: { card: Card | null }) {
  if (!card) return <section className="panel">Loading compliance…</section>
  return (
    <section className="panel">
      <h2>Why this part has to go</h2>
      <p>
        <strong>Compliance:</strong> {card.domestic_pct}% domestic (lines at{' '}
        {card.thresholds_pct.join('% / ')}%)
      </p>
      <p>
        <strong>US final assembly:</strong> {card.us_final_assembly ? 'yes' : 'no, required'}
      </p>
      <p>
        <strong>Supply risk:</strong> {card.supply_risks.join(', ') || 'none flagged'}
      </p>
      <ul className="notes">
        {card.notes.map((n) => (
          <li key={n}>{n}</li>
        ))}
      </ul>
    </section>
  )
}
import { STAGE_ORDER } from '../events'
import type { JobState } from '../job'

interface Props {
  state: JobState
  onStart: () => void
  /** Shown only with ?live=1 in the URL: starts a real (credit-spending) TinyFish job. */
  onStartLive?: () => void
}

export function JobBar({ state, onStart, onStartLive }: Props) {
  const running = state.connection === 'starting' || state.connection === 'streaming'
  const current = state.stage ? STAGE_ORDER.indexOf(state.stage) : -1
  const failed = state.stage === 'FAILED' || state.stage === 'DEGRADED'

  return (
    <section className="panel jobbar">
      <div className="jobbar-row">
        <button className="primary" onClick={onStart} disabled={running}>
          {running ? 'Running…' : state.jobId ? 'Run again' : 'Find and Redesign'}
        </button>
        {onStartLive && (
          <button className="secondary" onClick={onStartLive} disabled={running}>
            Run live
          </button>
        )}
        {state.mode && (
          <span className={`badge ${state.mode === 'live' ? 'badge-live' : 'badge-replay'}`}>
            {state.mode === 'live' ? 'LIVE' : 'REPLAY'}
          </span>
        )}
        {state.jobId && <span className="muted">job {state.jobId}</span>}
        {failed && <span className="badge badge-bad">{state.stage}</span>}
      </div>
      {state.jobId && (
        <ol className="stepper">
          {STAGE_ORDER.map((stage, i) => (
            <li
              key={stage}
              className={i < current ? 'done' : i === current ? 'current' : ''}
              title={stage}
            >
              {stage.replace('_', ' ').toLowerCase()}
            </li>
          ))}
        </ol>
      )}
      {state.errors.map((e) => (
        <p key={e} className="error">
          {e}
        </p>
      ))}
    </section>
  )
}
import type { ClaimRow } from '../job'

// Every number links to the page it came from. Only verified claims reach the checks.
export function ClaimsList({ claims }: { claims: ClaimRow[] }) {
  return (
    <section className="panel">
      <h2>Claims</h2>
      {claims.length === 0 ? (
        <p className="muted">Facts the agents bring back appear here once the verifier checks them.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th />
              <th>Field</th>
              <th>Value</th>
              <th>Quote on the page</th>
              <th>Source</th>
            </tr>
          </thead>
          <tbody>
            {claims.map(({ claim, verified, reason }) => (
              <tr key={claim.id} className={verified ? '' : 'rejected'}>
                <td title={verified ? `verified (${claim.verify_method})` : (reason ?? 'rejected')}>
                  {verified ? '✅' : '❌'}
                </td>
                <td>{claim.field.replaceAll('_', ' ')}</td>
                <td>
                  {claim.raw_value} {claim.raw_unit ?? ''}
                </td>
                <td>
                  <q>{claim.quote}</q>
                  {!verified && reason ? <div className="error">{reason}</div> : null}
                </td>
                <td>
                  <a href={claim.source.url} target="_blank" rel="noreferrer">
                    {new URL(claim.source.url, window.location.href).hostname}
                  </a>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  )
}
import { useEffect, useState } from 'react'
import { api } from './api'
import { AgentTiles } from './components/AgentTiles'
import { BeforeAfterViewer } from './components/BeforeAfterViewer'
import { ChecksTable } from './components/ChecksTable'
import { ClaimsList } from './components/ClaimsList'
import { ComplianceCard } from './components/ComplianceCard'
import { DesignTabs } from './components/DesignTabs'
import { JobBar } from './components/JobBar'
import { ModelViewer } from './components/ModelViewer'
import { useJob } from './job'
import type { CheckResult, ComplianceCard as Card, DesignVariant } from './types'

// ?live=1 shows a "Run live" button. The token is asked once per tab and kept in sessionStorage.
const LIVE_ENABLED = new URLSearchParams(window.location.search).get('live') === '1'
const TOKEN_KEY = 'live-jobs-token'

function startLive(start: (mode: 'live', token?: string) => void) {
  let token: string | null = null
  try {
    token = sessionStorage.getItem(TOKEN_KEY)
  } catch {
    // storage blocked: just ask every time
  }
  token ??= window.prompt('Live jobs spend TinyFish credit. Enter the live token:')
  if (!token) return
  try {
    sessionStorage.setItem(TOKEN_KEY, token)
  } catch {
    // ignore
  }
  start('live', token)
}

export default function App() {
  const [health, setHealth] = useState<string>('checking…')
  const [baselineCard, setBaselineCard] = useState<Card | null>(null)
  // Checks and designs stay on the pre-v3 endpoints until the coordinated shape switch.
  const [results, setResults] = useState<CheckResult[]>([])
  const [designs, setDesigns] = useState<DesignVariant[]>([])
  const { state: job, start } = useJob()

  useEffect(() => {
    api.health().then((h) => setHealth(h.status), () => setHealth('backend unreachable'))
    api.compliance().then(setBaselineCard, console.error)
    api.designs().then(setDesigns, console.error)
    api
      .seedCandidates()
      .then((cs) => Promise.all(cs.map(api.checks)))
      .then(setResults, console.error)
  }, [])

  const runs = job.runOrder.map((id) => job.runs[id])

  return (
    <main>
      <header>
        <h1>AI Robot Redesign Engine</h1>
        <span className="muted">API: {health}</span>
      </header>
      <JobBar
        state={job}
        onStart={() => start('replay')}
        onStartLive={LIVE_ENABLED ? () => startLive(start) : undefined}
      />
      {job.baseline && job.candidates[0] ? (
        <BeforeAfterViewer before={job.baseline} after={job.candidates[0]} />
      ) : (
        <ModelViewer src="/cad/designs/starter/glb" />
      )}
      <div className="grid">
        <ComplianceCard card={job.compliance ?? baselineCard} />
        <AgentTiles runs={runs} />
      </div>
      <ClaimsList claims={job.claims} />
      <ChecksTable results={results} />
      <DesignTabs designs={designs} />
      <footer className="muted">
        Not legal advice. Pass* = passes the checks we implemented, not engineering certification.
      </footer>
    </main>
  )
}
