/** Demo projects (data/projects/<id>.json on the backend). '' = today's wheeled demo robot. */
export const PROJECTS = [
  { id: '', label: 'Wheeled demo' },
  { id: 'stretch', label: 'Stretch' },
  { id: 'ar4_club', label: 'AR4 club' },
] as const

export type ProjectId = (typeof PROJECTS)[number]['id']

interface Props {
  value: ProjectId
  onChange: (id: ProjectId) => void
  disabled?: boolean
}

export function ProjectSwitcher({ value, onChange, disabled }: Props) {
  return (
    <div className="switcher" role="radiogroup" aria-label="Project">
      {PROJECTS.map((p) => (
        <button
          key={p.id}
          role="radio"
          aria-checked={value === p.id}
          className={value === p.id ? 'active' : ''}
          onClick={() => onChange(p.id)}
          disabled={disabled}
        >
          {p.label}
        </button>
      ))}
    </div>
  )
}

