                  <td>{line.domain}</td>
                  <td>{line.qty}</td>
                  <td className="chips">
                    {RISK_FACTORS.map((name) => {
                      const f = risk.factors.find((x) => x.name === name)
                      return (
                        <LevelChip
                          key={name}
                          level={f?.level ?? 'unknown'}
                          title={f ? `${f.value} · ${f.reason}` : 'not assessed'}
                        >
                          {name}
                        </LevelChip>
                      )
                    })}
                  </td>
                  <td>
                    <LevelChip level={risk.overall} />
                  </td>
                </tr>
                {alts.length > 0 && (
                  <tr className="subrow">
                    <td colSpan={5}>
                      <Alternatives alts={alts} />
                    </td>
                  </tr>
                )}
              </Fragment>
            )
          })}
        </tbody>
      </table>
    </section>
  )
}

