  background: transparent;
  color: inherit;
  border: 0;
  border-right: 1px solid var(--border);
  padding: 8px 12px;
  cursor: pointer;
}
.switcher button:last-child {
  border-right: 0;
}
.switcher button.active {
  background: var(--accent);
  color: #fff;
}
.switcher button:disabled {
  cursor: default;
  opacity: 0.7;
}
.panel h3 {
  font-size: 0.95rem;
  margin: 16px 0 6px;
}
.facts {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 4px;
}
.badge-verified {
  background: var(--live);
  text-decoration: none;
}
.badge-stated {
  background: var(--unknown);
}
.badge-illustrative {
  background: var(--medium);
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}
.chip {
  font-size: 0.75rem;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid currentColor;
  white-space: nowrap;
}
.level-low {
  color: var(--low);
}
.level-medium {
  color: var(--medium);
}
.level-high {
  color: var(--high);
  font-weight: 600;
}
.level-unknown {
  color: var(--unknown);
  border-style: dashed;
}
.subrow td {
  padding-top: 0;
}
table.nested {
  margin: 6px 0 4px;
  font-size: 0.9rem;
}
.action {
  font-weight: 600;
}
.action-re_source {
  color: var(--high);
}
.action-dual_source {
  color: var(--medium);
}
.action-keep {
  color: var(--low);
}
EOF
